     3→import type { Property } from "@/generated/prisma";
     4→
     5→type MockDPEAnalysis = {
     6→  dpe: {
     7→    id: string;
     8→    address: string;
     9→    postalCode: string;
    10→    city: string;
    11→    propertyType: string;
    12→    surface: number;
    13→    yearBuilt: number;
    14→    livingArea: number;
    15→    energyConsumption: {
    16→      value: number;
    17→      unit: string;
    18→      maxAuthorized: number;
    19→      class: string;
    20→    };
    21→    gesEmission: {
    22→      value: number;
    23→      unit: string;
    24→      maxAuthorized: number;
    25→      class: string;
    26→    };
    27→    mainEnergyType: string;
    28→    dpeDate: string;
    29→    dpeValidity: string;
    30→    dataSource: string;
    31→    lastUpdated: string;
    32→  };
    33→  estimatedAnnualCost: number;
    34→  estimatedMonthlyCost: number;
    35→  rentalRestrictionRisk: string;
    36→  renovationRequired: boolean;
    37→  renovationPriority: string;
    38→  estimatedRenovationCost: number;
    39→  performanceScore: number;
