    53→export type FavoriteEnrichmentResult = {
    54→  favoriteId: string;
    55→  success: boolean;
    56→  dpeData?: unknown;
    57→  error?: string;
    58→}
    59→
    60→export class FavoriteEnrichmentService {
    61→  private readonly dpeService: DPEService;
    62→
    63→  constructor() {
    64→    this.dpeService = new DPEService({
    65→      useMockData: process.env.NODE_ENV === "development",
    66→      cacheResults: true,
    67→      cacheTTL: 3600000, // 1 hour
    68→    });
    69→  }
    70→
    71→  /**
    72→   * Enrichit un favori avec les données DPE
    73→   */
    74→  async enrichFavoriteWithDPE(favoriteId: string): Promise<FavoriteEnrichmentResult> {
    75→    try {
    76→      // Récupérer le favori avec les données du bien
    77→      const prisma = new PrismaClient();
    78→      const favorite = await prisma.favorite.findUnique({
    79→        where: { id: favoriteId },
    80→        include: {
    81→          property: true,
    82→        },
    83→      });
    84→
    85→      if (!favorite) {
    86→        throw new Error(`Favorite ${favoriteId} not found`);
    87→      }
    88→
    89→      // Préparer les données du bien pour l'analyse DPE
    90→      const propertyForAnalysis = {
    91→        address: favorite.property.address,
    92→        postalCode: favorite.property.postalCode,
    93→        city: favorite.property.city,
    94→        surface: favorite.property.surface ?? 80, // Surface par défaut si non disponible
    95→        yearBuilt: this.estimateYearBuilt(favorite.property),
    96→        propertyType: this.normalizePropertyType(favorite.property.category),
    97→      };
    98→
    99→      // Note: Les coordonnées ne sont pas accessibles via Prisma pour les géométries
   100→
   101→      // Analyser le bien avec le service DPE
   102→      const dpeAnalysis = await this.dpeService.analyzeProperty(propertyForAnalysis);
   103→
   104→      // Mettre à jour le favori avec les données DPE
   105→      await prisma.favorite.update({
   106→        where: { id: favoriteId },
   107→        data: {
   108→          dpeClass: dpeAnalysis.dpe.energyConsumption.class,
   109→          gesClass: dpeAnalysis.dpe.gesEmission.class,
   110→          energyConsumption: dpeAnalysis.dpe.energyConsumption.value,
   111→          gesEmission: dpeAnalysis.dpe.gesEmission.value,
   112→          annualEnergyCost: dpeAnalysis.estimatedAnnualCost,
   113→          rentalRestrictionRisk: dpeAnalysis.rentalRestrictionRisk,
   114→          renovationRequired: dpeAnalysis.renovationRequired,
   115→          estimatedRenovationCost: dpeAnalysis.estimatedRenovationCost,
   116→          energyAnalysis: dpeAnalysis,
   117→          // Mettre à jour le score de confiance
   118→          confidenceScore: this.calculateConfidenceScore(dpeAnalysis),
   119→        },
   120→      });
   121→
   122→      return {
   123→        favoriteId,
   124→        success: true,
   125→        dpeData: dpeAnalysis,
   126→      };
   127→    } catch (error) {
   128→      console.debug(`Failed to enrich favorite ${favoriteId} with DPE data:`, error);
   129→
   130→      // Même en cas d'erreur, on essaie de générer des données mockées
   131→      try {
   132→        const mockAnalysis = await this.generateMockDPEAnalysis(favoriteId);
   133→        const prisma = new PrismaClient();
   134→        await prisma.favorite.update({
   135→          where: { id: favoriteId },
   136→          data: {
   137→            dpeClass: mockAnalysis.dpe.energyConsumption.class,
   138→            gesClass: mockAnalysis.dpe.gesEmission.class,
   139→            energyConsumption: mockAnalysis.dpe.energyConsumption.value,
   140→            gesEmission: mockAnalysis.dpe.gesEmission.value,
   141→            annualEnergyCost: mockAnalysis.estimatedAnnualCost,
   142→            rentalRestrictionRisk: mockAnalysis.rentalRestrictionRisk,
   143→            renovationRequired: mockAnalysis.renovationRequired,
   144→            estimatedRenovationCost: mockAnalysis.estimatedRenovationCost,
   145→            energyAnalysis: mockAnalysis,
   146→            confidenceScore: 50, // Score moyen pour les données mockées
   147→          },
   148→        });
   149→
   150→        return {
   151→          favoriteId,
   152→          success: true,
   153→          dpeData: mockAnalysis,
   154→        };
   155→      // eslint-disable-next-line @typescript-eslint/no-unused-vars
   156→      } catch (_mockError) {
   157→        return {
   158→          favoriteId,
   159→          success: false,
   160→          error: error instanceof Error ? error.message : "Unknown error",
   161→        };
   162→      }
   163→    }
   164→  }
   165→
   166→  /**
   167→   * Enrichit plusieurs favoris en parallèle
   168→   */
   169→  async enrichMultipleFavorites(favoriteIds: string[]): Promise<FavoriteEnrichmentResult[]> {
   170→    const promises = favoriteIds.map(async id => this.enrichFavoriteWithDPE(id));
   171→    return Promise.all(promises);
   172→  }
   173→
   174→  /**
   175→   * Enrichit tous les favoris d'un utilisateur
   176→   */
   177→  async enrichUserFavorites(userId: string): Promise<FavoriteEnrichmentResult[]> {
   178→    const prisma = new PrismaClient();
   179→    const favorites = await prisma.favorite.findMany({
   180→      where: { 
   181→        userId,
   182→        // N'enrichir que les favoris sans données DPE ou avec données anciennes
   183→        OR: [
   184→          { dpeClass: null },
   185→          { energyAnalysis: { equals: Prisma.DbNull } },
   186→          { updatedAt: { lt: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000) } } // Plus de 7 jours
   187→        ]
   188→      },
   189→    });
   190→
   191→    const favoriteIds = favorites.map((f) => f.id);
   192→    return this.enrichMultipleFavorites(favoriteIds);
   193→  }
   194→
   195→  /**
   196→   * Enrichit tous les favoris sans données DPE
   197→   */
   198→  async enrichAllFavoritesWithoutDPE(): Promise<FavoriteEnrichmentResult[]> {
   199→    const prisma = new PrismaClient();
   200→    const favorites = await prisma.favorite.findMany({
   201→      where: {
   202→        dpeClass: null,
   203→        energyAnalysis: { equals: Prisma.DbNull },
   204→      },
   205→    });
   206→
   207→    const favoriteIds = favorites.map((f) => f.id);
   208→    
   209→    // Traiter par lots de 10 pour éviter les surcharges
   210→    const results: FavoriteEnrichmentResult[] = [];
   211→    const batches: string[][] = [];
   212→    for (let i = 0; i < favoriteIds.length; i += 10) {
   213→      batches.push(favoriteIds.slice(i, i + 10));
   214→    }
   215→
   216→    for (let i = 0; i < batches.length; i++) {
   217→      const batch = batches[i];
   218→      // Traitement par lots - await en boucle intentionnel pour éviter les surcharges
   219→      // eslint-disable-next-line no-await-in-loop
   220→      const batchResults = await this.enrichMultipleFavorites(batch);
   221→      results.push(...batchResults);
   222→
   223→      // Petite pause entre les lots
   224→      if (i < batches.length - 1) {
   225→        // eslint-disable-next-line no-await-in-loop
   226→        await new Promise((resolve) => setTimeout(resolve, 1000));
   227→      }
   228→    }
   229→
   230→    return results;
   231→  }
   232→
   233→  /**
   234→   * Génère une analyse DPE simulée pour les fallbacks
   235→   */
   236→  private async generateMockDPEAnalysis(favoriteId: string): Promise<MockDPEAnalysis> {
   237→    const prisma = new PrismaClient();
   238→    const favorite = await prisma.favorite.findUnique({
   239→      where: { id: favoriteId },
   240→      include: { property: true },
   241→    });
   242→
   243→    if (!favorite) {
   244→      throw new Error(`Favorite ${favoriteId} not found`);
   245→    }
   246→
   247→    const surface = favorite.property.surface ?? 80;
   248→    const yearBuilt = this.estimateYearBuilt(favorite.property);
   249→    
   250→    // Logique de génération de données réalistes basées sur l'âge du bien
   251→    let energyClass = "D";
   252→    let energyConsumption = 200;
   253→    
   254→    if (yearBuilt < 1975) {
   255→      energyClass = "F";
   256→      energyConsumption = 350;
   257→    } else if (yearBuilt < 1990) {
   258→      energyClass = "E";
   259→      energyConsumption = 280;
   260→    } else if (yearBuilt < 2000) {
   261→      energyClass = "D";
   262→      energyConsumption = 220;
   263→    } else if (yearBuilt < 2010) {
   264→      energyClass = "C";
   265→      energyConsumption = 150;
   266→    } else {
   267→      energyClass = "B";
   268→      energyConsumption = 100;
   269→    }
   270→
   271→    return {
   272→      dpe: {
   273→        id: `mock_${favoriteId}`,
   274→        address: favorite.property.address,
   275→        postalCode: favorite.property.postalCode,
   276→        city: favorite.property.city,
   277→        propertyType: this.normalizePropertyType(favorite.property.category),
   278→        surface,
   279→        yearBuilt,
   280→        livingArea: surface,
   281→        energyConsumption: {
   282→          value: energyConsumption,
   283→          unit: "kWh_ep/m².an",
   284→          maxAuthorized: 450,
   285→          class: energyClass,
   286→        },
   287→        gesEmission: {
   288→          value: Math.round(energyConsumption * 0.15),
   289→          unit: "kgCO2/m².an",
   290→          maxAuthorized: 80,
   291→          class: energyClass,
   292→        },
   293→        mainEnergyType: "electricity",
   294→        dpeDate: new Date().toISOString().split('T')[0],
   295→        dpeValidity: new Date(Date.now() + 10 * 365 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
   296→        dataSource: "mock",
   297→        lastUpdated: new Date().toISOString(),
   298→      },
   299→      estimatedAnnualCost: Math.round(energyConsumption * surface * 0.25),
   300→      estimatedMonthlyCost: Math.round(energyConsumption * surface * 0.25 / 12),
   301→      rentalRestrictionRisk: energyClass === "F" || energyClass === "G" ? "critical" : "low",
   302→      renovationRequired: energyClass === "F" || energyClass === "G" || energyClass === "E",
   303→      renovationPriority: energyClass === "G" ? "high" : energyClass === "F" ? "medium" : "low",
   304→      estimatedRenovationCost: energyClass === "G" ? 25000 : energyClass === "F" ? 15000 : energyClass === "E" ? 8000 : 0,
   305→      performanceScore: energyClass === "A" ? 95 : energyClass === "B" ? 85 : energyClass === "C" ? 70 : energyClass === "D" ? 55 : energyClass === "E" ? 40 : energyClass === "F" ? 25 : 15,
   306→      energyEfficiencyRating: energyClass === "A" || energyClass === "B" ? "excellent" : energyClass === "C" || energyClass === "D" ? "good" : energyClass === "E" ? "average" : energyClass === "F" ? "poor" : "very_poor",
   307→      environmentalImpactRating: energyClass === "A" || energyClass === "B" ? "excellent" : energyClass === "C" ? "good" : energyClass === "D" ? "average" : energyClass === "E" ? "poor" : "very_poor",
   308→      recommendations: this.generateMockRecommendations(energyClass),
   309→      analysisDate: new Date().toISOString(),
   310→      confidenceLevel: "medium",
   311→      dataSource: "mock",
   312→    };
   313→  }
   314→
   315→  /**
   316→   * Calcule un score de confiance basé sur l'analyse DPE
   317→   */
   318→  private calculateConfidenceScore(dpeAnalysis: {
   319→    dataSource?: string;
   320→    confidenceLevel?: string;
   321→    dpe: { energyConsumption: { class: string } };
   322→  }): number {
   323→    let score = 50; // Score de base
   324→
   325→    // Bonus pour les données réelles vs mockées
   326→    if (dpeAnalysis.dataSource === "api") {
   327→      score += 30;
   328→    } else if (dpeAnalysis.dataSource === "mock") {
   329→      score += 10;
   330→    }
   331→
   332→    // Bonus pour la qualité des données
   333→    if (dpeAnalysis.confidenceLevel === "high") {
   334→      score += 20;
   335→    } else if (dpeAnalysis.confidenceLevel === "medium") {
   336→      score += 10;
   337→    }
   338→
   339→    // Malus pour les classes d'énergie mauvaises (peuvent indiquer des données peu fiables)
   340→    if (dpeAnalysis.dpe.energyConsumption.class === "G") {
   341→      score -= 10;
   342→    }
   343→
   344→    return Math.min(100, Math.max(0, score));
   345→  }
   346→
   347→  /**
   348→   * Estime l'année de construction basée sur les caractéristiques du bien
   349→   */
   350→  private estimateYearBuilt(property: Property): number {
   351→    // Logique simple d'estimation - peut être améliorée
   352→    const currentYear = new Date().getFullYear();
   353→    
   354→    if (property.floor && property.totalFloors && property.floor > property.totalFloors * 0.8) {
   355→      // Dernier étage = probablement plus récent
   356→      return currentYear - 20;
   357→    }
   358→    
   359→    if (property.hasLift) {
   360→      // Avec ascenseur = probablement construit après 1970
   361→      return 1980;
   362→    }
   363→    
   364→    // Par défaut, estimation conservatrice
   365→    return 1975;
   366→  }
   367→
   368→  /**
   369→   * Normalise le type de propriété
   370→   */
   371→  private normalizePropertyType(category: string): string {
   372→    const typeMap: Record<string, string> = {
   373→      apartment: "apartment",
   374→      house: "house",
   375→      commercial: "other",
   376→      default: "apartment",
   377→    };
   378→    
   379→    return typeMap[category.toLowerCase()] || typeMap.default;
   380→  }
   381→
   382→  /**
   383→   * Extrait les coordonnées du champ geometry
   384→   */
   385→  private extractCoordinates(coordinates: unknown): [number, number] | null {
   386→    if (!coordinates) return null;
   387→    
   388→    try {
   389→      // Le format peut varier, ceci est une gestion simple
   390→      if (Array.isArray(coordinates) && coordinates.length === 2) {
   391→        return coordinates as [number, number];
   392→      }
   393→      
   394→      if (typeof coordinates === 'string') {
   395→        const coords = coordinates.split(',').map(Number);
   396→        if (coords.length === 2 && !isNaN(coords[0]) && !isNaN(coords[1])) {
   397→          return coords as [number, number];
   398→        }
   399→      }
   400→      
   401→      return null;
   402→    } catch {
   403→      return null;
   404→    }
   405→  }
   406→
   407→  /**
   408→   * Génère des recommandations simulées
   409→   */
   410→  private generateMockRecommendations(energyClass: string): {
   411→    category: string;
   412→    description: string;
   413→    estimatedCost: number;
   414→    priority: string;
   415→  }[] {
   416→    const recommendations: {
   417→      category: string;
   418→      description: string;
   419→      estimatedCost: number;
   420→      priority: string;
   421→    }[] = [];
   422→
   423→    if (energyClass === "G" || energyClass === "F") {
   424→      recommendations.push({
   425→        category: "Isolation",
   426→        description: "Isolation thermique des murs et combles",
   427→        estimatedCost: 12000,
   428→        priority: "high",
   429→      });
   430→      recommendations.push({
   431→        category: "Chauffage",
   432→        description: "Installation d'une chaudière à haute performance",
   433→        estimatedCost: 8000,
   434→        priority: "high",
   435→      });
   436→      recommendations.push({
   437→        category: "Menuiseries",
   438→        description: "Remplacement des fenêtres par du double vitrage",
   439→        estimatedCost: 6000,
   440→        priority: "medium",
   441→      });
   442→    } else if (energyClass === "E") {
   443→      recommendations.push({
   444→        category: "Isolation",
   445→        description: "Amélioration de l'isolation des combles",
   446→        estimatedCost: 3000,
   447→        priority: "medium",
   448→      });
   449→    }
   450→
   451→    return recommendations;
   452→  }
   453→}

