    24→import { DVFClient } from "./client";
    25→import { DVFAnalyzer } from "./analyzer";
    26→import { dvfCache } from "./cache";
    27→import { logger } from "@/lib/logger";
    28→import type { Property } from "@/lib/moteurimmo/types";
    29→import type { DVFAnalysis } from "./types";
    30→
    31→/**
    32→ * Service principal DVF avec cache intégré
    33→ */
    34→export class DVFService {
    35→  private readonly analyzer: DVFAnalyzer;
    36→
    37→  constructor() {
    38→    const client = new DVFClient();
    39→    this.analyzer = new DVFAnalyzer(client);
    40→  }
    41→
    42→  /**
    43→   * Analyse un bien avec mise en cache automatique
    44→   */
    45→  async analyzeProperty(property: Property): Promise<DVFAnalysis> {
    46→    logger.debug("🏠 [DVFService] Début analyse avec cache", {
    47→      propertyId: property.id,
    48→      price: property.price,
    49→    });
    50→
    51→    // Vérifier le cache d'abord
    52→    const cached = await dvfCache.getAnalysis(property.id);
    53→    if (cached) {
